UPDATE courses SET
    course_description = '<h4>Course Overview</h4>The Advanced Diploma of Building Design (Architectural) at Holmesglen equips you with skills in residential and commercial building design by working on real-world projects that reflect authentic industry practices and client briefs. Through project-based learning, you will gain experience in Building Information Modelling (BIM), architectural design, and technical documentation in a supportive, collaborative environment, including opportunities for site visits, team discussions and industry seminars. You’ll have access to design studios, high-spec computer labs, and the latest technology, including Virtual and Mixed Reality, preparing you for a rewarding career in architectural design, building consultancy, drafting and sustainable building projects.',
    total_course_duration = 'Full Time 2 Year(s)',
    offshore_tuition_fee = 35280,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = '<h4>Entry Requirements</h4> 1. Good passes at Year 12 or the overseas equivalent. <p>2. English language proficiency equivalent to IELTS 6.0 or equivalent. For equivalent English language tests see <a href="https://immi.homeaffairs.gov.au/visas/getting-a-visa/visa-listing/student-500#Eligibility">https://immi.homeaffairs.gov.au/visas/getting-a-visa/visa-listing/student-500#Eligibility</a>.<br/> <br/>3. Students must be at least 18 at the commencement of the course. </p> <p> <h5>Recognition of prior learning</h5> </p> <p>You may be able to reduce the number of units to be studied in your chosen course by measuring skills acquired through work, life experiences or qualifications obtained from formal studies or training. AQF qualifications and statements of attainment issued by another registered training organisation will be recognised by Holmesglen. <a href="/current-students/course-resources/enrolment/advanced-standing-and-credits">Read more about Recognition of Prior Learning, Credits and Advanced Standing.</a></p>',
    apply_form = 'https://www.holmesglen.edu.au/explore-courses/building-and-construction/building-design-and-drafting/vocational-education/advanced-diploma-of-building-design-architectural-int',
    updated_at = NOW()
WHERE cricos_course_code = '114725D';

UPDATE courses SET
    course_description = '<h4>Course Overview</h4>Holmesglen’s Bachelor of Business (Accounting) prepares you for a successful career in accounting, finance and business management. This nationally recognised accounting degree combines practical, job-ready skills with real-world industry learning. Study in small, supportive classes and gain hands-on experience in financial accounting, taxation, auditing and advisory services. With accountants in high demand across Melbourne and Australia, graduates are well prepared for career opportunities across the public and private sectors. Accredited by <a href="https://www.cpaaustralia.com.au/">CPA Australia</a> and <a href="https://www.charteredaccountantsanz.com/">Chartered Accountants ANZ</a>.',
    total_course_duration = 'Full Time 3 Year(s)',
    offshore_tuition_fee = 62250,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = '<h4>Entry Requirements</h4> To be eligible for entry into the Bachelor of Business Accounting, international applicants must meet the following requirements:<p><strong>Age Requirement</strong><p>• Applicants must be at least 18 years of age at the commencement of the course.<p><strong>English Language Requirements</strong><p><strong>English Language Proficiency Requirements</strong><p>To meet the English language proficiency requirements of this course, you will need to demonstrate the following:<p>• IELTS overall score of 6.0 (Academic) or <a href="https://www.holmesglen.edu.au/study-with-us/international-student-study/how-to-apply-international-students/English-requirements-for-international-students">equivalent English language Tests</a><p><strong>Academic Requirements</strong><p>• Successful completion of VCE Year 12, or overseas equivalent. Applicants can access information on whether their overseas qualification is equivalent to the VCE Year 12 at <a href="https://www.vcaa.vic.edu.au/assessment/results/applying-credit-and-recognition/equivalent-qualifications/assessment-overseas-qualification-vce-equivalence-year-12">Assessment of overseas qualification for VCE equivalence - Year 12 - Victorian Curriculum and Assessment Authority</a>.<p>Applicants may also be considered on the basis of:<p>• Completion of an Australian VET Diploma or Advanced Diploma (or equivalent) in a relevant discipline; or<p>• Partial or completed higher education study at a recognised university or non university higher education provider.<p>All applications are assessed on an individual basis in accordance with Holmesglen’s admissions policies.<p>Applicants who have completed the Certificate IV in Accounting and Bookkeeping and Diploma of Accounting at Holmesglen may be eligible to receive credit towards the first year of the Bachelor of Business Accounting degree, subject to the Holmesglen’s credit and recognition of prior learning policies.<p>Holmesglen graduates of Diploma of Accounting (including the Accounting Principles Entry Skill Set) or Diploma of Business (Business Development) delivered offshore in Ningbo China at Zhejiang Business and Technology Institute may be eligible to receive credit towards the first year of the Bachelor of Business Accounting degree, subject to the Holmesglen’s credit and recognition of prior learning policies.<p><strong>Recommended</strong><p>• Prior study or a good knowledge of Mathematics, Accounting, or Economics is recommended but not mandatory and may assist students in successfully undertaking the degree. </p></p></p></p></p></p></p></p></p></p></p></p></p></p></p></p> <p> <h5>Advanced standing</h5> </p> <p>You may be able to reduce the number of units to be studied in your chosen course by measuring skills acquired through work, life experiences or qualifications obtained from formal studies or training. <a href="/current-students/course-resources/enrolment/advanced-standing-and-credits">Read more about gaining advanced standing and credits.</a></p>',
    apply_form = 'https://www.holmesglen.edu.au/explore-courses/business-and-finance/accounting-and-financial-services/higher-education/bachelor-of-business-accounting-int',
    updated_at = NOW()
WHERE cricos_course_code = '091332D';

UPDATE courses SET
    course_description = '<h4>Course Overview</h4>The Bachelor of Digital Construction and Management at Holmesglen prepares you for leadership roles in the evolving construction and built environment sector. This demanding yet rewarding degree combines digital construction technologies, Industry 4.0 principles and hands-on learning. You''ll work on real industry projects, use immersive simulations, and collaborate across disciplines to build strong digital, technical and problem-solving skills. Graduates are job-ready and equipped to manage modern construction projects in a digital world.',
