UPDATE courses SET
    course_description = '<h4>Course Overview</h4>Turn technology into strategy. Shape the systems that power the digital world. From data analytics to software innovation and digital infrastructure — information systems drive the way modern organisations operate, compete, and grow. The Bachelor of Information Systems at Holmesglen gives you the skills to design, develop, and manage the digital solutions that power today’s businesses and shape tomorrow’s economy.You’ll learn how technology supports business transformation, how data informs strategic decisions, and how software connects people, systems, and information.Choose from three industry-aligned specialisation streams to tailor your studies to your career goals:• Data Analytics – harness the power of data to uncover insights and guide smarter decisions.• Software Development – design, code, and deliver innovative digital solutions.• General – develop a broad foundation across business systems, data, security, and infrastructure.This degree is accredited by the <a href="https://www.acs.org.au/">Australian Computer Society (ACS)</a>, providing industry recognition and ensuring your skills align with current and emerging technology industry standards.',
    total_course_duration = 'Full Time 3 Year(s)',
    offshore_tuition_fee = 64200,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = '<h4>Entry Requirements</h4> To be eligible for entry into the Bachelor of Information Systems, international applicants must meet the following requirements:<p><strong>Age Requirement</strong><p>• Applicants must be at least 18 years of age at the commencement of the course.<p><strong>English Language Proficiency Requirements</strong><p>To meet the English language proficiency requirements of this course, you will need to demonstrate the following:<p>• IELTS overall score of 6.0 (Academic) or <a href="https://www.holmesglen.edu.au/study-with-us/international-student-study/how-to-apply-international-students/English-requirements-for-international-students">equivalent English language Tests</a><p><strong>Academic Requirements</strong><p>• Successful completion of VCE Year 12, or overseas equivalent. Applicants can access information on whether their overseas qualification is equivalent to the VCE Year 12 at <a href="https://www.vcaa.vic.edu.au/assessment/results/applying-credit-and-recognition/equivalent-qualifications/assessment-overseas-qualification-vce-equivalence-year-12">Assessment of overseas qualification for VCE equivalence - Year 12 - Victorian Curriculum and Assessment Authority</a>.<p>Applicants may also be considered on the basis of:<p>• Completion of an Australian Diploma or Advanced Diploma (or equivalent) in a relevant discipline; or<p>• Partial or completed higher education study at a recognised university or non university higher education provider.<p>All applications are assessed on an individual basis in accordance with Holmesglen’s admissions policies.<p>Graduates of the Diploma of Information Technology (Advanced Programming &amp; Back End Web Development) at Holmesglen may be eligible to receive credit towards the first year of the Bachelor of Information Systems, subject to the Holmesglen’s credit and recognition of prior learning policies. </p></p></p></p></p></p></p></p></p></p></p></p> <p> <h5>Advanced standing</h5> </p> <p>You may be able to reduce the number of units to be studied in your chosen course by measuring skills acquired through work, life experiences or qualifications obtained from formal studies or training. <a href="/current-students/course-resources/enrolment/advanced-standing-and-credits">Read more about gaining advanced standing and credits.</a></p>',
    apply_form = 'https://www.holmesglen.edu.au/explore-courses/computing-and-it/information-systems/higher-education/bachelor-of-information-systems-int',
    updated_at = NOW()
WHERE cricos_course_code = '095613G';

UPDATE courses SET
    course_description = '<h4>Course Overview</h4>The Bachelor of Nursing at Holmesglen prepares students for a rewarding career as a Registered Nurse through hands-on clinical training, simulation-based learning and evidence-based practice. This industry-focused nursing degree develops the clinical skills, critical thinking and leadership abilities required to deliver safe, person-centred care in modern healthcare environments. Students gain real-world experience through extensive clinical placements and state-of-the-art simulation labs guided by experienced educators and industry professionals. Accredited by the <a href="https://www.anmac.org.au/">Australian Nursing and Midwifery Accreditation Council (ANMAC)</a>, graduates are eligible to apply for registration with the <a href="https://www.ahpra.gov.au/">Australian Health Practitioner Regulation Agency (AHPRA)</a> as Registered Nurses.',
    total_course_duration = 'Full Time 3 Year(s)',
    offshore_tuition_fee = 99600,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = 1100,
    entry_requirements = '<h4>Entry Requirements</h4> To be eligible for entry into this course, applicants must meet the following requirements:<br/><strong>Age Requirement</strong><br/>Applicants must be at least 18 years of age at the commencement of the course.<p><strong>Academic Requirement</strong><br/>Successful completion of VCE Year 12, or overseas equivalent. For the overseas equivalent Year 12 qualification, see <a href="https://www.vcaa.vic.edu.au/assessment/results/applying-credit-and-recognition/equivalent-qualifications/assessment-overseas-qualification-vce-equivalence-year-12">Assessment of overseas qualification for VCE equivalence - Year 12 - Victorian Curriculum and Assessment Authority</a>.<p><strong>English Language Requirements</strong><br/>Applicants must have English language proficiency of:<br/>1. IELTS test (Academic), with a minimum overall score of 7 and component scores of, Listening-7, Reading-7, Speaking-7 and Writing- 6.5 OR <br/>2. Cambridge (C1 Advanced) with a minimum overall score of 178, and component scores as listening -175, reading- 179, speaking- 194 and writing- 180 OR <br/>3. Cambridge (C2 Proficiency) with a minimum overall score of 185, and component scores as listening -185, reading- 185, speaking- 185 and writing- 176 OR <br/>4. OET with a minimum component score in listening-350, reading-360, speaking-360 and writing -350 OR <br/>5. PTE Academic with a minimum overall score of 63 and component scores of, listening- 58, reading-59, speaking -76 and writing - 60 OR <br/>6. TOEFL iBT with a minimum overall score of 91 and component scores as, listening- 22, reading-22, writing-23, and speaking- 24.<p>For further information about English language proficiency requirements, please refer to the <a href="https://www.holmesglen.edu.au/study-with-us/international-student-study/how-to-apply-international-students/English-requirements-for-international-students">English requirements for international students</a>.<p><strong>Clinical Placement Requirements</strong><br/>Prior to undertaking clinical placement, Students must be a minimum of 18 years of age at the time of their first clinical placement. Additionally, students must be prepared to declare their health and immunisation status, complete a National Police Records Check annually and hold a valid Working with Children Check.<br/>Immunisations required include:<br/>• Measles/Mumps/Rubella<br/>• Hepatitis A<br/>• Hepatitis B<br/>• Tuberculous screening<br/>• Diphtheria/Tetanus/Pertussis<br/>• Polio<br/>• Influenza<br/>• Varicella </p></p></p></p> <p> <h5>Advanced standing</h5> </p> <p>You may be able to reduce the number of units to be studied in your chosen course by measuring skills acquired through work, life experiences or qualifications obtained from formal studies or training. <a href="/current-students/course-resources/enrolment/advanced-standing-and-credits">Read more about gaining advanced standing and credits.</a></p>',
    apply_form = 'https://www.holmesglen.edu.au/explore-courses/nursing-community-and-health-sciences/nursing/higher-education/bachelor-of-nursing-int',
    updated_at = NOW()
WHERE cricos_course_code = '103159J';

UPDATE courses SET
    course_description = '<h4>Course Overview</h4>The Bachelor of Oral Health (Therapy and Hygiene) is a Charles Sturt University degree offered at Holmesglen''s Chadstone. Students will undertake lectures and pre-clinical training in Years 1 and 2 at Holmesglen, with some clinical training at Charles Sturt University ''s campus in Wagga Wagga, NSW. The third year of the course is completed while enrolled at the Wagga Wagga campus of Charles Sturt University.<p>CRICOS 00005F | TEQSA PRV12018</p>',
    total_course_duration = '',
    offshore_tuition_fee = NULL,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = '<h4>Entry Requirements</h4> Applicant needs ATAR 70 or equivalent and applicants should apply directly to CSU or VTAC (if they meet the VTAC criteria)<br/>.<p>English language proficiency equivalent to IELTS 7.0 (Academic) with no individual bandscores less than 7.0.<br/>For equivalent English language tests see <a href="https://immi.homeaffairs.gov.au/visas/getting-a-visa/visa-listing/student-500#Eligibility">https://immi.homeaffairs.gov.au/visas/getting-a-visa/visa-listing/student-500#Eligibility</a>.<p>Successful applicants are encouraged to obtain a senior first aid certificate prior to commencing the course.<br/>Prior to commencement of the first placement students will also be required to provide evidence of their immunisation and vaccination status, and a completed Working with Children Check. </p></p> <p> <h5>Advanced standing</h5> </p> <p>You may be able to reduce the number of units to be studied in your chosen course by measuring skills acquired through work, life experiences or qualifications obtained from formal studies or training. <a href="/current-students/course-resources/enrolment/advanced-standing-and-credits">Read more about gaining advanced standing and credits.</a></p>',
    apply_form = 'https://www.holmesglen.edu.au/explore-courses/nursing-community-and-health-sciences/dental/higher-education/bachelor-of-oral-health-therapy-and-hygiene-int',
    updated_at = NOW()
WHERE cricos_course_code = '077426D';

UPDATE courses SET
    course_description = '<h4>Course Overview</h4>The Bachelor of Sport Business prepares students for careers across the dynamic and competitive sports industry. This degree develops practical skills in sport management, marketing, commercial sport, sports media and sport development. Delivered in partnership with the <a href="https://www.holmesglen.edu.au/about-us/our-institute/partners-and-projects/local-industry-partners/saints-sports-program">St Kilda Football Club</a>, students gain real-world experience through strong industry engagement, including guest speakers, field trips and a 228-hour internship with leading sporting organisations. Delivered in small, supportive classes by experienced industry professionals, the course equips graduates with the knowledge, confidence and industry connections to succeed in professional sport, government, venues and sports events.',
    total_course_duration = 'Full Time 3 Year(s)',
    offshore_tuition_fee = 65850,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = '<h4>Entry Requirements</h4> To be eligible for entry into the Bachelor of Sport Business, international applicants must meet the following requirements:<p><strong>Age Requirement</strong><p>• Applicants must be at least 18 years of age at the commencement of the course.<p><strong>English Language Proficiency Requirements</strong><p>To meet the English language proficiency requirements of this course, you will need to demonstrate the following:<p>• IELTS overall score of 6.0 (Academic) or <a href="https://www.holmesglen.edu.au/study-with-us/international-student-study/how-to-apply-international-students/English-requirements-for-international-students">equivalent English language Tests</a><p><strong>Academic Requirements</strong><p>• Successful completion of VCE Year 12, or overseas equivalent. Applicants can access information on whether their overseas qualification is equivalent to the VCE Year 12 at <a href="https://www.vcaa.vic.edu.au/assessment/results/applying-credit-and-recognition/equivalent-qualifications/assessment-overseas-qualification-vce-equivalence-year-12">Assessment of overseas qualification for VCE equivalence - Year 12 - Victorian Curriculum and Assessment Authority</a>.<p>Applicants may also be considered on the basis of:<p>• Completion of an Australian Diploma or Advanced Diploma (or equivalent) in a relevant discipline; or<p>• Partial or completed higher education study at a recognised university or non university higher education provider.<p>All applications are assessed on an individual basis in accordance with Holmesglen’s admissions policies.<p>Applicants who have completed Dual Diploma of SIS50321 Diploma of Sports and SIT50322 Diploma of Event Management at Holmesglen may be eligible to receive credit towards the first year of the Bachelor of Sport Business, subject to the Holmesglen’s credit and recognition of prior learning policies. </p></p></p></p></p></p></p></p></p></p></p></p> <p> <h5>Advanced standing</h5> </p> <p>You may be able to reduce the number of units to be studied in your chosen course by measuring skills acquired through work, life experiences or qualifications obtained from formal studies or training. <a href="/current-students/course-resources/enrolment/advanced-standing-and-credits">Read more about gaining advanced standing and credits.</a></p>',
    apply_form = 'https://www.holmesglen.edu.au/explore-courses/sport-fitness-and-wellbeing/sport/higher-education/bachelor-of-sport-business-int',
    updated_at = NOW()
WHERE cricos_course_code = '092390G';

UPDATE courses SET
    course_description = '<h4>Course Overview</h4>The Bachelor of Sports Media prepares students for careers in the fast-paced sports and digital media industry. Designed to reflect today’s evolving media landscape, the degree develops practical skills in sports media production, content creation and communication. Delivered in partnership with the <a href="https://www.holmesglen.edu.au/about-us/our-institute/partners-and-projects/local-industry-partners/saints-sports-program">St Kilda Football Club</a>, the course provides strong industry engagement and internship opportunities. Graduates gain an industry-ready skill set suited to roles across sports journalism, broadcasting, digital media and social platforms, supported by valuable real-world experience and professional networks.',
