UPDATE courses SET
    course_description = '<h4>Course Overview</h4>The SFL30115 Certificate III in Floristry at Holmesglen provides practical, industry-focused training to prepare you for a career as a professional florist. This hands-on floristry course develops your skills in flower design, including handheld, wired and base arrangements, while building your creativity in event styling and visual display. You’ll also gain experience in customer service and retail floristry, essential for working in flower shops and creative businesses. Guided by experienced floristry teachers, you’ll create real designs and may participate in industry events such as the Melbourne International Flower and Garden Show, graduating job-ready for the floristry industry.',
    total_course_duration = 'Full Time 1 Year(s)',
    offshore_tuition_fee = 15640,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = 830,
    entry_requirements = '<h4>Entry Requirements</h4> 1. Good passes at Year 11 or the overseas equivalent. <p>2. English language proficiency level of IELTS 6.0, ISLPR 2+, TOEFL 197 (CB) or 46 (iBT), PTE Academic Score of 42 (no communicative skill score less than 42), Cambridge English: Certificate in Advanced English (CAE) of 47 or equivalent. For equivalent English language tests see <a href="https://immi.homeaffairs.gov.au/visas/getting-a-visa/visa-listing/student-500#Eligibility">https://immi.homeaffairs.gov.au/visas/getting-a-visa/visa-listing/student-500#Eligibility</a>.<br/> <br/>3. Students must be at least 18 at the commencement of the course.<p>4. International applicants are required to achieve ACSF Level 2 in the online Literacy and Numeracy testing (BKSB). </p></p> <p> <h5>Recognition of prior learning</h5> </p> <p>You may be able to reduce the number of units to be studied in your chosen course by measuring skills acquired through work, life experiences or qualifications obtained from formal studies or training. AQF qualifications and statements of attainment issued by another registered training organisation will be recognised by Holmesglen. <a href="/current-students/course-resources/enrolment/advanced-standing-and-credits">Read more about Recognition of Prior Learning, Credits and Advanced Standing.</a></p>',
    apply_form = 'https://www.holmesglen.edu.au/explore-courses/horticulture-and-environment/floristry/vocational-education/certificate-iii-in-floristry-int',
    updated_at = NOW()
WHERE cricos_course_code = '089027J';

UPDATE courses SET
    course_description = '<h4>Course Overview</h4>The HLT37215 Certificate III in Pathology Collection prepares you for a rewarding career as a pathology collector or phlebotomist in the healthcare sector. This nationally recognised course provides hands-on training in phlebotomy, blood and specimen collection, laboratory procedures, and patient care, giving you the practical skills and clinical knowledge to work confidently in pathology clinics, hospitals, medical centres, and diagnostic laboratories. Whether you are starting your healthcare career or transitioning into pathology, this qualification develops the technical expertise, workplace experience, and professional skills needed to support medical teams, ensure patient safety, and excel in a variety of healthcare roles.',
    total_course_duration = 'Full Time 5 Months',
    offshore_tuition_fee = 10380,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = '<h4>Entry Requirements</h4> 1. Good passes at Year 12 or the overseas equivalent. <p>2. English language proficiency equivalent to IELTS 6.0 or equivalent. For equivalent English language tests see <a href="https://immi.homeaffairs.gov.au/visas/getting-a-visa/visa-listing/student-500#Eligibility">https://immi.homeaffairs.gov.au/visas/getting-a-visa/visa-listing/student-500#Eligibility</a>.<br/> <br/>3. Students must be at least 18 at the commencement of the course.<p>In order to comply with the recommendations of the Australian Government, Department of Health, and current pathology placement requirements, learners must provide the following serology evidence prior to course commencement:<p>- Hepatitis B Surface antibodies<br/>- Hepatitis C <br/>- Hepatitis A Ab<br/>- HIV<br/>- Measles / Mumps / Rubella<br/>- (MMR)Varicella<br/>- Chicken Pox<br/>- Diphtheria, Tetanus &amp; Pertussis<br/>- Polio<br/>- Tuberculosis<br/>- COVID-19 including booster<br/>- Influenza<p>Learners will be required to pass a national police records check prior to placements, and meet clinical placement immunisation requirements stated above.<p>Typically, eligible learners will have the ability to:<br/>• Interact, communicate and work in small teams<br/>• Comprehend technical reading material (Instrumentation Manuals, Standard Operating Procedures and Material Safety Data Sheets etc.)<br/>• Problem solve such as identifying when data is outside expected results and identifying possible causes<br/>• Apply basic digital literacy<br/> A physical ability to stand for long periods and fine motor control are recommended. </p></p></p></p></p> <p> <h5>Recognition of prior learning</h5> </p> <p>You may be able to reduce the number of units to be studied in your chosen course by measuring skills acquired through work, life experiences or qualifications obtained from formal studies or training. AQF qualifications and statements of attainment issued by another registered training organisation will be recognised by Holmesglen. <a href="/current-students/course-resources/enrolment/advanced-standing-and-credits">Read more about Recognition of Prior Learning, Credits and Advanced Standing.</a></p>',
    apply_form = 'https://www.holmesglen.edu.au/explore-courses/nursing-community-and-health-sciences/pathology-and-laboratory-testing/vocational-education/certificate-iii-in-pathology-collection-int',
    updated_at = NOW()
WHERE cricos_course_code = '095314G';

