UPDATE courses SET
    course_description = '<h4>Course Overview</h4>The MSL40122 Certificate IV in Laboratory Techniques prepares students for careers as laboratory technicians in pathology, biotechnology, food testing, environmental science, education and research laboratories. This nationally recognised qualification combines practical laboratory training with industry-focused learning to develop skills in laboratory operations, sample preparation, chemical and biological testing, microscopy, data analysis, laboratory documentation and quality control. Train using industry-standard laboratory equipment in Holmesglen''s specialised pathology and biotechnology laboratories while learning safe laboratory practices from experienced science educators. Graduate with the practical skills, technical knowledge and confidence to work in laboratory settings or continue your studies in laboratory science and related scientific fields.',
    total_course_duration = 'Full Time 1 Year(s)',
    offshore_tuition_fee = 18440,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = '<h4>Entry Requirements</h4> 1. Good passes at Year 12 or the overseas equivalent. <p>2. English language proficiency equivalent to IELTS 6.0 or equivalent. For equivalent English language tests see <a href="https://immi.homeaffairs.gov.au/visas/getting-a-visa/visa-listing/student-500#Eligibility">https://immi.homeaffairs.gov.au/visas/getting-a-visa/visa-listing/student-500#Eligibility</a>.<br/> <br/>3. Students must be at least 18 at the commencement of the course.<p><strong>Recommended skills: </strong><br/>• Ability to follow instructions accurately<br/>• Strong English communication for reporting and collaboration<br/>• Attention to detail for laboratory testing<br/>• Familiarity with digital technologies for online learning<br/><strong>Digital readiness: </strong><br/>• Access to a computer, laptop, or tablet with a headset is highly recommended for online activities via Holmesglen’s Brightspace LMS.<br/><strong>Laboratory participation:<br/>• No special physical requirements beyond standard lab activities<br/>• Must handle equipment and samples safely and follow protocols </strong></p></p> <p> <h5>Recognition of prior learning</h5> </p> <p>You may be able to reduce the number of units to be studied in your chosen course by measuring skills acquired through work, life experiences or qualifications obtained from formal studies or training. AQF qualifications and statements of attainment issued by another registered training organisation will be recognised by Holmesglen. <a href="/current-students/course-resources/enrolment/advanced-standing-and-credits">Read more about Recognition of Prior Learning, Credits and Advanced Standing.</a></p>',
    apply_form = 'https://www.holmesglen.edu.au/explore-courses/nursing-community-and-health-sciences/pathology-and-laboratory-testing/vocational-education/certificate-iv-in-laboratory-techniques-int',
    updated_at = NOW()
WHERE cricos_course_code = '112036A';

UPDATE courses SET
    course_description = '<h4>Course Overview</h4>The Certificate IV in Patisserie at Holmesglen provides hands-on training in Melbourne’s top simulated commercial kitchens. Perfect for aspiring pastry chefs, this course covers specialised techniques in chocolate, desserts, cakes, pastries, and buffet showpieces. Students also gain skills in food safety, dietary requirements, and team management, preparing them for diverse pastry and pastry career opportunities. This practical, non-apprenticeship program is ideal for those seeking a professional patisserie qualification.Learners will be involved in a two-week practical placement.This qualification provides a pathway to work in various organisations where patisserie products are prepared and served, including patisseries, restaurants, hotels, catering operations, clubs, pubs, cafés, and coffee shops.',
