    offshore_tuition_fee = 17900,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = '<h4>Entry Requirements</h4> 1. Good passes at Year 11 or the overseas equivalent. <p>2. English language proficiency equivalent to IELTS 6.0 or equivalent. For equivalent English language tests see <a href="https://immi.homeaffairs.gov.au/visas/getting-a-visa/visa-listing/student-500#Eligibility">https://immi.homeaffairs.gov.au/visas/getting-a-visa/visa-listing/student-500#Eligibility</a>.<br/> <br/>3. Students must be at least 18 at the commencement of the course. </p> <p> <h5>Recognition of prior learning</h5> </p> <p>You may be able to reduce the number of units to be studied in your chosen course by measuring skills acquired through work, life experiences or qualifications obtained from formal studies or training. AQF qualifications and statements of attainment issued by another registered training organisation will be recognised by Holmesglen. <a href="/current-students/course-resources/enrolment/advanced-standing-and-credits">Read more about Recognition of Prior Learning, Credits and Advanced Standing.</a></p>',
    apply_form = 'https://www.holmesglen.edu.au/explore-courses/computing-and-it/programming/vocational-education/diploma-of-information-technology-advanced-programming-with-diploma-of-information-technology-back-end-web-development-ict50220-int',
    updated_at = NOW()
