UPDATE courses SET
    course_description = '<h4>Course Overview</h4>Holmesglen’s Diploma of Nursing prepares you with the practical skills, clinical knowledge and hands-on experience required to become an Enrolled Nurse. Learn from industry-current Registered Nurses in state-of-the-art simulated hospital environments at our <a href="https://www.holmesglen.edu.au/about-us/campuses/moorabbin">Moorabbin campus</a> and <a href="https://www.holmesglen.edu.au/about-us/campuses/bourke-street">Bourke Street campus</a>. Through immersive learning and 400 hours of supported clinical placements across aged care, acute, mental health and community healthcare settings, you’ll build the confidence to deliver evidence-based, person-centred care. Holmesglen also registers all learners with the Australian Health Practitioner Regulation Agency (AHPRA).',
    total_course_duration = 'Full Time 18 Months',
    offshore_tuition_fee = 39090,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = 1100,
    entry_requirements = '<h4>Entry Requirements</h4> Learners enrolling in HLT54121 Diploma of Nursing must demonstrate they have achieved the Nursing and Midwifery Board of Australia (NMBA) specified level of English language skills prior to commencing the course. Many learners will have English as a Second Language.<br/><strong>English language requirements</strong><br/>• IELTS test (Academic), with a minimum overall score of 7 and component scores of Listening 7, Reading 7, Speaking 7 and Writing 6.5 OR <br/>• Cambridge (C1 Advanced) with a minimum overall score of 178, and component scores of Listening 175, Reading 179, Speaking 194 and Writing 180 OR <br/>• Cambridge (C2 Proficiency) with a minimum overall score of 185, and component scores of Listening 185, Reading 185, Speaking 185 and Writing 176 OR <br/>• OET with a minimum component score in Listening 350, Reading 360, Speaking 360 and Writing 350 OR <br/>• PTE Academic with a minimum overall score of 63 and component scores of Listening 58, Reading 59, Speaking 76 and Writing 60 OR <br/>• TOEFL iBT with a minimum overall score of 91 and component scores of Listening 22, Reading 22, Writing 23 and Speaking 24. <p><strong>Academic and age requirements</strong><br/>• All international learners must have passes at Year 12 or the overseas equivalent, with passes in all subjects including Mathematics. <br/>• International learners must be at least 18 years of age by 6 months into course commencement. <p><strong>Clinical placement requirements</strong><br/>• Prior to undertaking clinical placement, learners must have applied for, obtained, and produced a current and valid Australian National Police Records Check, a current Police Records Check from their overseas country of residence (English translation), a NDIS Worker Screening Check, a Working with Children Check in Australia, and be prepared to declare their health, Australian immunisation and vaccination status that includes a booster shot (third) COVID-19 vaccination record. Note that a COVID vaccine is recommended but no longer mandatory.<p><strong>Inherent requirements</strong><br/>• The inherent requirements are the abilities, knowledge and skills needed to complete the course that must be met by all learners. <br/>• The nursing team members can work collaboratively with you, if required, to determine reasonable adjustments to assist you to meet the inherent requirements. <br/>• In cases where it is determined that inherent requirements cannot be met with reasonable adjustments, the Holmesglen team members can provide guidance regarding other study options. </p></p></p> <p> <h5>Recognition of prior learning</h5> </p> <p>You may be able to reduce the number of units to be studied in your chosen course by measuring skills acquired through work, life experiences or qualifications obtained from formal studies or training. AQF qualifications and statements of attainment issued by another registered training organisation will be recognised by Holmesglen. <a href="/current-students/course-resources/enrolment/advanced-standing-and-credits">Read more about Recognition of Prior Learning, Credits and Advanced Standing.</a></p>',
    apply_form = 'https://www.holmesglen.edu.au/explore-courses/nursing-community-and-health-sciences/nursing/vocational-education/diploma-of-nursing-int',
    updated_at = NOW()
WHERE cricos_course_code = '108196H';

